Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='gatebuildonce', at=datetime(2026, 10, 11, 0, 0, 0), actor='assistant', title='Each thing is built once in a gate, and no build is incremental', body="EACH THING IS BUILT ONCE (2026-10-11, the `gate-build-once` report): one debug build serves the tests and the named suites, and e2e's fixture shares its dependencies (the fixture turns on the core's `fixture`, so the workspace's crates compile a second time); the shells link with mold and the dev profile optimises the dependencies; and the live half builds HEAD's public tree with the deploy's own list on the box (`deploy-build`), so the deploy of a landed commit only links. No build is incremental (2026-10-10).", rationale='Decided 2026-10-11 (the gate-build-once report); no build is incremental since 2026-10-10.', supersedes=()))